import {nativeBridge,installMobileShell} from './platform.mjs';
installMobileShell();
function enhance(root=document){for(const b of root.querySelectorAll('button')){if(/^[×✕✖]$/.test(b.textContent.trim())){b.classList.add('realm-close');if(!b.hasAttribute('aria-label'))b.setAttribute('aria-label','关闭');}if(b.hasAttribute('data-exit-app')){b.hidden=!nativeBridge()?.quit;if(!b.dataset.exitBound){b.dataset.exitBound='1';b.addEventListener('click',()=>nativeBridge()?.quit());}}}}
enhance();new MutationObserver(records=>{for(const r of records)for(const el of r.addedNodes)if(el.nodeType===1){enhance(el);if(el.matches('button')&&/^[×✕✖]$/.test(el.textContent.trim())){el.classList.add('realm-close');if(!el.hasAttribute('aria-label'))el.setAttribute('aria-label','关闭');}}}).observe(document.body,{childList:true,subtree:true});
